public class Ticket { private final String ticketId,bookingId,eventName,holder; public Ticket(String ticketId,String bookingId,String eventName,String holder){this.ticketId=ticketId;this.bookingId=bookingId;this.eventName=eventName;this.holder=holder;} public String getTicketId(){return ticketId;} public String toFileLine(){return ticketId+"|"+bookingId+"|"+eventName+"|"+holder;} public String toString(){return "---------- EVENT TICKET ----------\nTicket ID : "+ticketId+"\nBooking ID: "+bookingId+"\nEvent     : "+eventName+"\nName      : "+holder+"\n----------------------------------";} }
